# Helper for ablation edits on attention output projections
import torch, numpy as np
FULL_ATTN = [3,7,11,15,19,23]
def set_attn_edit(layers, mode='zero', frac=0.0):
    clear_edits()
    for L in layers:
        n = f'model.language_model.layers.{L}.self_attn.o_proj.weight'
        W = load_original(n).numpy().astype(np.float32)
        if mode=='zero': Wn = W*0.0
        elif mode=='scale': Wn = W*frac
        save_edit(n, torch.from_numpy(Wn).float())
def clear_attn_edit():
    for L in FULL_ATTN:
        try: drop_edit(f'model.language_model.layers.{L}.self_attn.o_proj.weight')
        except Exception: pass
print('ok')

